package cl.dynasty.nexusbeacon.platform.classic;
import java.io.File;import java.util.ArrayList;import java.util.List;import org.bukkit.command.PluginCommand;import org.bukkit.configuration.file.FileConfiguration;import org.bukkit.plugin.Plugin;import org.bukkit.plugin.PluginManager;
public final class ClassicApplication {private final Plugin plugin;private final ClassicPlatform platform;private ClassicApplicationState state;private ClassicRecipeManager recipes;private ClassicVisualRuntime visuals;private ClassicBeamRuntime beams;private ClassicEffectCatalog effects;
 public ClassicApplication(Plugin p,ClassicPlatform platform){plugin=p;this.platform=platform;}
 public void start(FileConfiguration beacon,FileConfiguration effectsConfig,FileConfiguration language){state=new ClassicApplicationState(new ClassicYamlBeaconStorage(new File(plugin.getDataFolder(),"storage.yml")));ClassicStorageLoad load=state.initialize();if(!load.isSuccessful())throw new IllegalStateException("Classic storage "+load.getStatus()+": "+load.getDiagnostic());String name=language.getString("item.display-name","&b&lNexusBeacon");List<String> lore=language.getStringList("item.lore");if(lore.isEmpty()){lore=new ArrayList<String>();lore.add("&7A configurable custom beacon.");}ClassicBeaconItemFactory items=new ClassicBeaconItemFactory(platform.getItemIdentity(),name,lore);ClassicBeaconTransactions tx=new ClassicBeaconTransactions(state,platform.getItemIdentity(),beacon.getInt("beacon.default-range",48),beacon.getBoolean("protection.protect-base-blocks",true),beacon.getBoolean("beacon.particles.enabled",true),beacon.getString("beacon.particles.type","VILLAGER_HAPPY"));this.effects=new ClassicEffectCatalog(effectsConfig.getConfigurationSection("effects"),new ClassicMaterialResolver(),new ClassicPotionEffectResolver());ClassicParticleResolver particles=new ClassicParticleResolver();ClassicBeamStyleCatalog guiBeams=new ClassicBeamStyleCatalog(beacon,particles);ClassicCoreListener listener=new ClassicCoreListener(state,tx,items,beacon.getBoolean("protection.owner-only-break",true),beacon.getBoolean("beacon-item.auto-pickup",true),beacon.getBoolean("beacon-item.creative-no-dupe",true),effects,guiBeams);PluginManager pm=plugin.getServer().getPluginManager();pm.registerEvents(listener,plugin);recipes=new ClassicRecipeManager(plugin,items);if(!recipes.register(beacon.getConfigurationSection("recipe")))throw new IllegalStateException("Classic recipe registration failed");PluginCommand command=plugin.getServer().getPluginCommand("NexusBeacon");if(command==null)throw new IllegalStateException("NexusBeacon command missing");ClassicNexusBeaconCommand commandHandler=new ClassicNexusBeaconCommand(state,items);command.setExecutor(commandHandler);command.setTabCompleter(commandHandler);visuals=new ClassicVisualRuntime(plugin,state,particles,beacon.getInt("beacon.particles.radius-points",96));visuals.start(Math.max(1L,beacon.getLong("beacon.particles.interval-ticks",20L)));beams=ClassicBeamRuntime.create(plugin,state,beacon,particles,platform.getServices().getScheduler());beams.start();plugin.getLogger().info("Classic application: "+state.size()+" managed beacons, recipe registered, "+beams.getStyleCount()+" beam styles, "+effects.getSupportedDefinitions().size()+" supported definitions, "+effects.getDeferredExecutors().size()+" deferred executors; Vault optional and paid actions disabled.");}
 public void stop(){if(beams!=null)beams.close();if(visuals!=null)visuals.stop();if(recipes!=null)recipes.unregister();if(state!=null)state.close();org.bukkit.event.HandlerList.unregisterAll(plugin);}public ClassicApplicationState getState(){return state;}public ClassicEffectCatalog getEffects(){return effects;}}
